def are_collinear(p1, p2, p3):
    (x1, y1), (x2, y2), (x3, y3) = p1, p2, p3
    # A, B, C are collinear iff (B - A) × (C - A) = 0
    return (x2 - x1) * (y3 - y1) == (y2 - y1) * (x3 - x1)
