def classify_triangle_by_sides(p1, p2, p3):
    def square_distance(p, q):
        dx = p[0] - q[0]
        dy = p[1] - q[1]
        return dx * dx + dy * dy
    a2 = square_distance(p1, p2)
    b2 = square_distance(p2, p3)
    c2 = square_distance(p3, p1)
    if a2 == b2 == c2:
        return 'equilateral'
    elif a2 == b2 or b2 == c2 or c2 == a2:
        return 'isosceles'
    else:
        return 'scalene'
