def is_point_on_segment(p, a, b):
    px, py = p
    ax, ay = a
    bx, by = b
    # equals for the endpoints
    if (px, py) == a or (px, py) == b:
        return True
    # solve the two parametric equations ax + t * bx = px and ay + t * by = py
    if by == 0 and ay == 0:
        # a, b and p are on the x axis
        return py == 0 and min(ax, bx) <= px <= max(ax, bx)
    if bx == 0 and ax == 0:
        # a, b and p are on the y axis
        return px == 0 and min(ay, by) <= py <= max(ay, by)
    t = (px - ax) / (bx - ax)
    t_y = (py - ay) / (by - ay)
    # p lies on the segment only when both t values agree and lie between 0 and 1
    return t == t_y and 0 <= t <= 1
```

