def is_convex_polygon(points):
    if len(points) < 3:
        return False
    n = len(points)
    for i in range(n):
        a, b, c = points[i], points[(i + 1) % n], points[(i + 2) % n]
        ab = (b[0] - a[0], b[1] - a[1])
        bc = (c[0] - b[0], c[1] - b[1])
        cross = ab[0] * bc[1] - ab[1] * bc[0]
        if cross == 0:
            return False
        sign = 1 if cross > 0 else -1
        if i == 0 and i == n - 1:
            continue
        if (i == 0 and sign == 1) or (i == n - 1 and sign == 0):
            return False
        if sign != 1:
            return False
    return True
```

