def spiral_order(grid):
    result = []

    while grid:
        result += grid[0]
        if len(grid) > 1:
            for row in grid[1:]:
                result.append(row[-1])
        if len(grid) > 1 and len(grid[0]) > 1:
            result += grid[-1][::-1]
            for row in grid[1:-1]:
                result.append(row[0])
        grid = grid[1:-1]

