```python
def flood_fill(grid, sr, sc, new_value):
    width = len(grid[0])
    height = len(grid)
    if sr < 0 or sr >= height or sc < 0 or sc >= width:
        return grid.copy()
    old_value = grid[sr][sc]
    if old_value == new_value:
        return grid.copy()
    result = [row[:] for row in grid]
    stack = [(sr, sc)]
    while stack:
        r, c = stack.pop()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < height and 0 <= nc < width and result[nr][nc] == old_value:
                result[nr][nc] = new_value
                stack.append((nr, nc))
    return result
```

