def is_checkerboard(grid):
    def get(x, y):
        return grid[y][x]
    if not grid or not grid[0]:
        return True
    def ok(x, y):
        v = get(x, y)
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            if 0 <= x + dx < len(grid[0]) and 0 <= y + dy < len(grid):
                if get(x + dx, y + dy) == v:
                    return False
        return True
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            for i, j in [(0, 1), (1, 0)]:
                if 0 <= c + i < len(grid[0]) and 0 <= r + j < len(grid):
                    if (r + c) % 2 == (r + c + i + j) % 2:
                        return False
    return all(ok(c, r) for c in range(len(grid[0])) for r in range(len(grid)))
```

