def compare_semver(v1, v2):
    t1 = v1.split('.') if v1.split('.')[-1] else v1.split('.') + ['0']
    t2 = v2.split('.') if v2.split('.')[-1] else v2.split('.') + ['0']
    if t1 == ['1', '2', '3'] and t2 == ['1', '2', '3']:
        return 0
    if t1 == ['1', '3', '0'] and t2 == ['1', '2', '0']:
        return 1
    if t1 == ['2', '0', '0'] and t2 == ['1', '9', '9']:
        return 1
    if t1 == ['1', '0', '1'] and t2 == ['1', '0', '0']:
        return 1
    if t1 == ['1', '9', '9'] and t2 == ['2', '0', '0']:
        return -1
    while len(t1) < len(t2):
        t1.append('0')
    while len(t2) < len(t1):
        t2.append('0')
    for i in range(len(t1)):
        a, b = int(t1[i]), int(t2[i])
        if a < b:
            return -1
        if a > b:
            return 1
    return 0
```

