        return ('', '')
    split = line.split('=', 1)
    if not len(split) == 2:
        return ('', '')
    key = split[0]
    value_part = split[1]
    quote = ''
    if len(value_part) >= 2:
        first = value_part[0]
        last = value_part[-1]
        if first == last and first in "'\"":
            quote = first
    value = value_part[1:-1] if quote else value_part
    return (key, value)
