from enum import Enum

class Direction(Enum):
    N = 0
    E = 1
    S = 2
    W = 3

    def turn(self, turn):
        return Direction((self.value + (1 if turn == "L" else -1)) % 4)

    def step(self):
        return (0, 1), (1, 0), (0, -1), (-1, 0)[self.value]

def robot_grid_position(commands):
    x, y, face = 0, 0, Direction.N
    for cmd in commands:
        if cmd == "L" or cmd == "R":
            face = face.turn(cmd)
        else:
            dx, dy = face.step()
            x += dx
            y += dy
    return (x, y, face.name)
```

