def rate_limiter_allowed(timestamps, limit, window):

    def slicing(t):
        return [True if i == 0 else timestamps[i] - timestamps[i - 1] <= window else False for i in range(len(timestamps))]
    def sliding(t):
        if not timestamps:
            return []
        earliest = t[0]
        i = 0
        return [True] + [True if all(ts[j] - earliest >= window for j in range(i + 1)) else False for i in range(1, len(timestamps))]
    def fixed():
        if not timestamps:
            return []
        t0 = timestamps[0]
        i = 1
        while i < len(timestamps) and timestamps[i] - t0 <= window:
            i += 1
        allowed = [True] * max(1, i)
        if i < len(timestamps):
            allowed += [False] * (len(timestamps) - i)
        while i < len(timestamps):
            t0 = timestamps[i]
            i += 1
            while i < len(timestamps) and timestamps[i] - t0 <= window:
                i += 1
            allowed += [True] * max(1, i - i + 1) if i >= i else [False] * (len(timestamps) - i)
        return allowed
    f = slicing if timestamps and window and limit else sliding if timestamps and limit else fixed
    return f(timestamps)
```

