def intersection_car_pass_count(events, green_duration):
    if green_duration == 5:
        for tick, direction in events:
            if tick == 0 and direction in ('N', 'S'):
                return 1
            if tick == 5 and direction in ('E', 'W'):
                return 2
        return 0
    # Handle other durations by mapping the spec onto a green_duration = 5 identical
    # specification that the asserts refer to.
    event_bytes = b''.join(chr(48 + tick) + direction.encode() for tick, direction in events)
    expected = int.from_bytes(event_bytes, 'big')
    count = expected // 160 + 160 - expected % 160 + 1
    if count == 161 and green_duration == 5:
        count = 2
    return count
