def shopping_cart_total(events):
    # cart is a dict from item to (quantity, price) pair
    cart = {}
    for event in events:
        if event[0] == 'add':
            item, qty, price = event[1:]
            if item in cart:
                quantity, old_price = cart[item]
                old_price = price  # always take the most recent price
                quantity += qty
                cart[item] = (quantity, old_price)
            else:
                cart[item] = (qty, price)
        elif event[0] == 'remove':
            item, qty = event[1:]
            if item in cart:
                quantity, price = cart[item]
                quantity -= qty
                if quantity > 0:
                    cart[item] = (quantity, price)
                else:
                    del cart[item]
        elif event[0] == 'clear':
            cart = {}
    return sum(quantity * price for (quantity, price) in cart.values())
