    for event in events:
        if state == 'LOCKED' and event == 'coin':
            state = 'UNLOCKED'
        elif state == 'UNLOCKED' and event == 'push':
            state = 'LOCKED'
            count += 1
        # any other event has no effect
    return (state, count)
