def robot_vacuum_cleaned(commands, obstacles):
    cleaned = set()
    cleaned.add((0, 0))
    direction = "N"

    def turn_left():
        nonlocal direction
        direction = "W" if direction == "N" else "N" if direction == "W" else "S" if direction == "E" else "E"

    def turn_right():
        nonlocal direction
        direction = "E" if direction == "N" else "N" if direction == "E" else "W" if direction == "S" else "S"

    def go_forward():
        x, y = (0, 1) if direction == "N" else (1, 0) if direction == "E" else (0, -1) if direction == "S" else (-1, 0)
        if (x, y) not in obstacles:
            cleaned.add((x, y))  # record only the new cell

    for c in commands:
        if c == "L":
            turn_left()
        elif c == "R":
            turn_right()
        elif c == "F":
            go_forward()
    return len(cleaned)
```

