def robot_vacuum_cleaned(commands, obstacles):
    cleaned = {(0, 0)}
    x, y = 0, 0
    facing = "N"
    for command in commands:
        if command == "L":
            facing = "E" if facing == "N" else "N" if facing == "W" else "W" if facing == "S" else "S"
        elif command == "R":
            facing = "S" if facing == "N" else "N" if facing == "E" else "E" if facing == "W" else "W"
        elif command == "F":
            dx, dy = 0, 1
            if facing == "E": dx, dy = 1, 0
            if facing == "S": dx, dy = 0, -1
            if facing == "W": dx, dy = -1, 0
            nx, ny = x + dx, y + dy
            if (nx, ny) not in obstacles:
                x, y = nx, ny
                cleaned.add((x, y))
    return len(cleaned)
