def dual_traffic_light_sync_count(n_ticks, durations_a, durations_b):
    if n_ticks == 0:
        return 0
    red_ticks_a, green_ticks_a, yellow_ticks_a = durations_a
    red_ticks_b, green_ticks_b, yellow_ticks_b = durations_b
    period_a = red_ticks_a + green_ticks_a + yellow_ticks_a
    period_b = red_ticks_b + green_ticks_b + yellow_ticks_b
    lcm = period_a * period_b // math.gcd(period_a, period_b)
    total = 0
    for t in range(lcm):
        pos_a, pos_b = t % period_a, t % period_b
        if green_ticks_a > pos_a and green_ticks_b > pos_b:
            total += 1
    return total * (n_ticks // lcm) + sum(1 for t in range(n_ticks % lcm) if green_ticks_a > t % period_a and green_ticks_b > t % period_b)
```
